```openscad
// Small lab funnel, printed upright (wide rim on top, spout on the build plate).
// Built as a single rotate_extrude of the wall cross-section, so both ends are open.

$fn = 128;                       // smoothness of the revolved surface

// ---------------- Dimensions (mm) ----------------
wall        = 1.2;               // wall thickness (normal to every surface)
spout_od    = 10.0;              // spout outer diameter
spout_h     = 25.0;              // spout height (z = 0 to z = 25)
rim_od      = 40.0;              // cone outer diameter at the rim
total_h     = 60.0;              // overall height (rim at z = 60)

// ---------------- Derived values ----------------
spout_r_out = spout_od / 2;                  // 5.0  spout outer radius
spout_r_in  = spout_r_out - wall;            // 3.8  spout bore radius (7.6 mm bore)
rim_r_out   = rim_od / 2;                    // 20.0 rim outer radius
cone_h      = total_h - spout_h;             // 35.0 cone height
cone_k      = (rim_r_out - spout_r_out) / cone_h;   // radial growth per mm of height
cone_ang    = atan(cone_k);                  // cone wall angle from vertical
cone_hoff   = wall / cos(cone_ang);          // horizontal offset giving true 1.2 mm normal wall
rim_r_in    = rim_r_out - cone_hoff;         // inner radius at the rim
// height where the inner cone surface meets the spout bore
z_join_in   = spout_h + (cone_hoff - wall) / cone_k;

// ---------------- Wall cross-section (r, z) ----------------
module wall_profile() {
    polygon(points = [
        [spout_r_in,  0],          // bore, bottom
        [spout_r_out, 0],          // outer, bottom
        [spout_r_out, spout_h],    // outer, top of spout / start of cone
        [rim_r_out,   total_h],    // outer rim
        [rim_r_in,    total_h],    // inner rim
        [spout_r_in,  z_join_in]   // inner cone meets spout bore
    ]);
}

// ---------------- Part ----------------
rotate_extrude(convexity = 4)
    wall_profile();
```

```openscad
// Flat drilling/marking jig with 3 x 4 hole grid and orientation notch

// ---- Plate ----
plate_x     = 44;    // plate length (X)
plate_y     = 54;    // plate width (Y)
plate_t     = 4;     // plate thickness (Z)

// ---- Hole grid ----
hole_d      = 4.0;   // through-hole diameter
hole_pitch  = 10;    // centre-to-centre spacing (X and Y)
holes_nx    = 3;     // number of holes along X
holes_ny    = 4;     // number of holes along Y

// ---- Orientation notch (+Y edge) ----
notch_w     = 10;    // notch width (X)
notch_d     = 5;     // notch depth in from +Y edge (Y)

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces
$fn         = 64;    // circle resolution

difference() {
    // Plate, centred in XY, resting on z = 0
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // 3 x 4 grid of through-holes, centred on the plate
    for (i = [0 : holes_nx - 1])
        for (j = [0 : holes_ny - 1])
            translate([(i - (holes_nx - 1)/2) * hole_pitch,
                       (j - (holes_ny - 1)/2) * hole_pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps, $fn = 64);

    // Rectangular orientation notch on the +Y edge, centred on Y axis
    translate([-notch_w/2, plate_y/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2*eps]);
}
