```openscad
// Bench rack for 12 x 1.5 mL microcentrifuge tubes
// Print orientation: block rests on XY plane, holes open upward (+Z)

// ---------------- Block dimensions ----------------
block_x   = 80;    // block length (X)
block_y   = 62;    // block width (Y)
block_z   = 30;    // block height (Z)

// ---------------- Hole grid ----------------
cols      = 4;     // holes along X
rows      = 3;     // holes along Y
pitch_x   = 18;    // centre-to-centre spacing along X
pitch_y   = 18;    // centre-to-centre spacing along Y

// ---------------- Hole geometry ----------------
hole_d    = 11.2;  // hole diameter
hole_depth = 24;   // hole depth from top face
floor_t   = block_z - hole_depth; // solid floor thickness (6 mm)

// ---------------- Misc ----------------
overcut   = 0.5;   // cutter extension past the top face
$fn       = 96;    // curve resolution

// Grid origin offsets so the grid is centred on the block
grid_x0 = -(cols - 1) * pitch_x / 2;
grid_y0 = -(rows - 1) * pitch_y / 2;

difference() {
    // Solid block, centred in X/Y, sitting on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_z]);

    // Tube holes: start at floor_t, extend past top face
    for (i = [0 : cols - 1])
        for (j = [0 : rows - 1])
            translate([grid_x0 + i * pitch_x,
                       grid_y0 + j * pitch_y,
                       floor_t])
                cylinder(d = hole_d, h = hole_depth + overcut, $fn = 96);
}
```

