// Snap-on C-clip for 12.0 mm lab-stand rod
// Printed flat: 2-D profile in XY, extruded 15 mm in +Z

// ---------------- Parameters ----------------
rod_d      = 12.0;               // inner diameter (rod diameter)
wall       = 4.0;                // ring wall thickness
outer_d    = rod_d + 2*wall;     // outer diameter = 20.0
clip_h     = 15.0;               // extrusion height (Z)
gap_w      = 6.6;                // opening width in Y (-3.3 < y < 3.3)
cut_extra  = 1.0;                // overshoot of cutting shapes
$fn        = 128;                // smoothness of curves

// ---------------- Model ----------------
linear_extrude(height = clip_h)
    difference() {
        circle(d = outer_d);                         // outer ring
        circle(d = rod_d);                           // rod bore
        // opening on -X side: x < 0, -gap_w/2 < y < gap_w/2
        translate([-(outer_d/2 + cut_extra), -gap_w/2])
            square([outer_d/2 + cut_extra, gap_w]);
    }
