```openscad
// Two-part enclosure: box + lid (lid printed upside down), side by side on the bed
// Units: mm

$fn = 64;

// ---------- Box ----------
box_x     = 80;     // box outer length (X)
box_y     = 55;     // box outer width (Y)
box_z     = 22;     // box outer height (Z)
wall_t    = 1.6;    // box wall thickness
floor_t   = 1.6;    // box floor thickness

// ---------- Lid ----------
lid_x     = 80;     // lid plate length (X)
lid_y     = 55;     // lid plate width (Y)
lid_t     = 2.5;    // lid plate thickness
lip_x     = 76.2;   // lip outer length (X), 0.3 mm clearance per side
lip_y     = 51.2;   // lip outer width (Y), 0.3 mm clearance per side
lip_wall  = 2.0;    // lip wall thickness
lip_h     = 5;      // lip height above plate

// ---------- Layout ----------
gap       = 10;     // gap between box and lid on the bed
eps       = 0.5;    // overcut for clean differences
ovl       = 0.01;   // small overlap for unions

// Centre the pair on the origin in X
total_x   = box_x + gap + lid_x;
box_cx    = -total_x/2 + box_x/2;          // box centre X
lid_cx    =  total_x/2 - lid_x/2;          // lid centre X (on +X side)

// ---------- Part 1: Box (open top) ----------
module box() {
    difference() {
        translate([-box_x/2, -box_y/2, 0])
            cube([box_x, box_y, box_z]);
        translate([-(box_x - 2*wall_t)/2, -(box_y - 2*wall_t)/2, floor_t])
            cube([box_x - 2*wall_t, box_y - 2*wall_t, box_z - floor_t + eps]);
    }
}

// ---------- Part 2: Lid (upside down, lip pointing up) ----------
module lid() {
    union() {
        // plate
        translate([-lid_x/2, -lid_y/2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip wall
        translate([0, 0, lid_t - ovl])
            difference() {
                translate([-lip_x/2, -lip_y/2, 0])
                    cube([lip_x, lip_y, lip_h + ovl]);
                translate([-(lip_x - 2*lip_wall)/2, -(lip_y - 2*lip_wall)/2, -eps])
                    cube([lip_x - 2*lip_wall, lip_y - 2*lip_wall, lip_h + ovl + 2*eps]);
            }
    }
}

// ---------- Assembly on the bed ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
```

