// 8-place holder for glass HPLC vials, printed upright
// Units: mm

// Block dimensions
block_len   = 162;   // length along X
block_wid   = 28;    // width along Y
block_ht    = 20;    // height along Z

// Hole parameters
n_holes     = 8;     // number of vial holes
hole_pitch  = 19;    // centre-to-centre spacing along X
hole_d      = 11.6;  // hole diameter
hole_depth  = 17;    // blind hole depth from top
floor_t     = block_ht - hole_depth; // remaining floor thickness (3 mm)

// Cutting overlap
eps         = 0.5;   // extension past top face

$fn = 96;

difference() {
    // Solid block, centred in X and Y, resting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of blind holes, centred on the block in X and Y
    for (i = [0 : n_holes - 1]) {
        x = (i - (n_holes - 1) / 2) * hole_pitch;
        translate([x, 0, floor_t])
            cylinder(d = hole_d, h = hole_depth + eps, $fn = 96);
    }
}
