```openscad
// Push-on cap for 12.0 mm OD tube, printed open-end up
$fn = 96;

// --- Dimensions (mm) ---
tube_od      = 12.0;   // tube outer diameter (reference)
clearance    = 0.4;    // diametral clearance over tube
cap_od       = 17.8;   // cap outer diameter
cap_h        = 8.0;    // total cap height
bore_d       = tube_od + clearance; // 12.8 mm blind bore diameter
floor_t      = 2.5;    // closed cap (bottom) thickness
bore_depth   = cap_h - floor_t;     // 5.5 mm bore depth from top

groove_n     = 16;     // number of grip grooves
groove_d     = 2.0;    // grip groove diameter (half-cylinder on surface)
eps          = 0.5;    // overcut for clean booleans

difference() {
    // Main body
    cylinder(d = cap_od, h = cap_h);

    // Blind bore from the top
    translate([0, 0, floor_t])
        cylinder(d = bore_d, h = bore_depth + eps);

    // Vertical grip grooves, centred on the outer surface
    for (i = [0 : groove_n - 1])
        rotate([0, 0, i * 360 / groove_n])
            translate([cap_od / 2, 0, -eps])
                cylinder(d = groove_d, h = cap_h + 2 * eps, $fn = 48);
}
