```openscad
// Replacement control knob for 6.3 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

// ---------- Parameters ----------
knob_d        = 28.0;   // knob outer diameter
knob_h        = 20.0;   // knob total height

bore_d        = 6.5;    // D-bore circle diameter
bore_flat     = 5.0;    // distance from flat to opposite side of circle
bore_depth    = 16.0;   // blind bore depth from bottom face

groove_count  = 24;     // number of vertical grip grooves
groove_d      = 2.0;    // groove diameter (half-cylinder centred on outer surface)

eps           = 0.5;    // overshoot for clean boolean cuts
$fn           = 96;     // resolution for curved surfaces

// ---------- Derived ----------
knob_r        = knob_d / 2;
bore_r        = bore_d / 2;
flat_offset   = bore_flat - bore_r;   // flat position from bore centre (+X side)

// ---------- Modules ----------
module d_bore_2d() {
    intersection() {
        circle(d = bore_d, $fn = 96);
        // keep everything from the far side of the circle up to the flat
        translate([-bore_r - 1, -bore_r - 1])
            square([flat_offset + bore_r + 1, bore_d + 2]);
    }
}

module knob() {
    difference() {
        // main body
        cylinder(d = knob_d, h = knob_h);

        // D-shaped blind bore from the bottom face
        translate([0, 0, -eps])
            linear_extrude(height = bore_depth + eps)
                d_bore_2d();

        // vertical grip grooves along the full height
        for (i = [0 : groove_count - 1])
            rotate([0, 0, i * 360 / groove_count])
                translate([knob_r, 0, -eps])
                    cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 48);
    }
}

// ---------- Build ----------
knob();
