```openscad
// Weighted base for a vertical support rod
// Printed upright: disc on the bed, boss rising along +Z

$fn = 96;

// ---- Base disc ----
disc_d      = 100.0;  // disc diameter
disc_h      = 5.0;    // disc thickness (z = 0 to 5)

// ---- Central boss ----
boss_d      = 30.0;   // boss diameter
boss_top_z  = 30.0;   // top of boss (absolute z)

// ---- Rod bore ----
bore_d      = 10.0;   // blind bore diameter
bore_bot_z  = 5.0;    // bore floor (absolute z)

// ---- Set-screw hole ----
screw_d     = 5.0;    // radial set-screw hole diameter
screw_z     = 24.0;   // set-screw hole centre height

// ---- Cutting overlap ----
eps         = 0.5;    // extra length so cutters pass through faces

difference() {
    union() {
        // Base disc
        cylinder(d = disc_d, h = disc_h);
        // Boss (overlaps into disc for a clean union)
        translate([0, 0, disc_h - eps])
            cylinder(d = boss_d, h = boss_top_z - disc_h + eps);
    }

    // Blind rod bore from top of boss down to z = 5
    translate([0, 0, bore_bot_z])
        cylinder(d = bore_d, h = boss_top_z - bore_bot_z + eps);

    // Radial set-screw hole from +X outer surface into the bore
    translate([0, 0, screw_z])
        rotate([0, 90, 0])
            cylinder(d = screw_d, h = boss_d / 2 + eps);
}
