// L-shaped mounting bracket
// Print orientation: base plate flat on the bed (z = 0), vertical plate rising in +Z.
// Coordinates follow the user's spec exactly (X centred, Y from 0 at the back edge).

$fn = 64;

// ---------------- Base plate ----------------
base_x_min   = -20;   // base plate left edge (mm)
base_x_max   =  20;   // base plate right edge (mm)
base_y_min   =   0;   // base plate back edge (mm)
base_y_max   =  40;   // base plate front edge (mm)
base_thick   =   5;   // base plate thickness, z 0..5 (mm)

// ---------------- Vertical plate ----------------
vert_x_min   = -20;   // vertical plate left edge (mm)
vert_x_max   =  20;   // vertical plate right edge (mm)
vert_y_min   =   0;   // vertical plate back face (mm)
vert_y_max   =   5;   // vertical plate front face (mm)
vert_height  =  50;   // vertical plate height, z 0..50 (mm)

// ---------------- Holes ----------------
hole_d          = 3.4;   // clearance hole diameter (mm)
base_hole_xs    = [-12, 12]; // base hole X positions (mm)
base_hole_y     = 28;    // base hole Y position (mm)
vert_hole_xs    = [-12, 12]; // vertical plate hole X positions (mm)
vert_hole_z     = 35;    // vertical plate hole Z position (mm)

eps = 0.5;               // cutter overshoot past faces (mm)

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_x_max - base_x_min, base_y_max - base_y_min, base_thick]);

        // Vertical plate on back edge
        translate([vert_x_min, vert_y_min, 0])
            cube([vert_x_max - vert_x_min, vert_y_max - vert_y_min, vert_height]);
    }

    // Vertical through-holes in base plate (along Z)
    for (x = base_hole_xs)
        translate([x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_thick + 2 * eps, $fn = 64);

    // Horizontal through-holes in vertical plate (along Y)
    for (x = vert_hole_xs)
        translate([x, vert_y_min - eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = (vert_y_max - vert_y_min) + 2 * eps, $fn = 64);
}
