```openscad
// 16-well agarose gel comb - printed flat on the bed
// Units: mm

$fn = 64;

// ---------------- Parameters ----------------
plate_t      = 2.0;    // plate thickness (Z) = well thickness
spine_len    = 112;    // spine (back bar) length (X)
spine_w      = 12;     // spine width (Y)
n_teeth      = 16;     // number of teeth / wells
tooth_w      = 5.0;    // tooth width (X)
tooth_len    = 12;     // tooth length (Y), hanging in -Y from spine
tooth_gap    = 1.5;    // gap between neighbouring teeth (X)
overlap      = 0.5;    // teeth overlap into spine for a clean union

// Derived
pitch        = tooth_w + tooth_gap;                       // 6.5 mm
row_len      = n_teeth * tooth_w + (n_teeth - 1) * tooth_gap; // 102.5 mm
total_y      = spine_w + tooth_len;                       // 24 mm
y_edge       = total_y / 2 - spine_w;                     // spine/teeth junction (y = 0)

// ---------------- Model ----------------
union() {
    // Spine: from y = y_edge to y = +total_y/2
    translate([-spine_len / 2, y_edge, 0])
        cube([spine_len, spine_w, plate_t]);

    // Teeth: hang from the spine edge toward -Y, row centred in X
    for (i = [0 : n_teeth - 1])
        translate([-row_len / 2 + i * pitch, y_edge - tooth_len, 0])
            cube([tooth_w, tooth_len + overlap, plate_t]);
}
```

