```openscad
// Small lab funnel - printed upright, wide opening at top
// All dimensions in mm

$fn = 96;

// ---- Parameters ----
spout_od      = 10.0;   // spout outer diameter
spout_h       = 15.0;   // spout height (z = 0 .. 15)
rim_od        = 45.0;   // cone outer diameter at rim
total_h       = 55.0;   // rim height (top of funnel)
wall          = 2.4;    // wall thickness (perpendicular to surface)
eps           = 1.0;    // overshoot for clean boolean cuts

// ---- Derived values ----
cone_h        = total_h - spout_h;                    // cone height (40)
spout_bore_d  = spout_od - 2 * wall;                  // spout bore (5.2)
cone_slope    = (rim_od - spout_od) / 2 / cone_h;     // radial growth per mm of z
cone_angle    = atan(cone_slope);                     // half-angle of cone from vertical
wall_radial   = wall / cos(cone_angle);               // radial offset giving 2.4 mm normal wall

// Inner cone radii (outer radius minus radial wall offset), extended past top
inner_r_bot   = spout_od / 2 - wall_radial;           // at z = spout_h
inner_r_top   = rim_od / 2 - wall_radial + cone_slope * eps; // at z = total_h + eps

module funnel() {
    difference() {
        // Outer solid
        union() {
            cylinder(d = spout_od, h = spout_h);
            translate([0, 0, spout_h])
                cylinder(d1 = spout_od, d2 = rim_od, h = cone_h);
        }
        // Spout bore - runs fully through for open bottom
        translate([0, 0, -eps])
            cylinder(d = spout_bore_d, h = total_h + 2 * eps);
        // Inner cone cavity - extends past rim for open top
        translate([0, 0, spout_h])
            cylinder(r1 = inner_r_bot, r2 = inner_r_top, h = cone_h + eps);
    }
}

funnel();
```

