// Flat drilling/marking jig with 3 x 5 hole grid and orientation notch
// Print orientation: plate flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_l   = 46;    // plate length along X (mm)
plate_w   = 62;    // plate width along Y (mm)
plate_t   = 4;     // plate thickness along Z (mm)

hole_d    = 5.0;   // through-hole diameter (mm)
pitch     = 8;     // centre-to-centre hole spacing, X and Y (mm)
n_x       = 3;     // number of hole columns along X
n_y       = 5;     // number of hole rows along Y

notch_w   = 10;    // orientation notch width along X (mm)
notch_d   = 5;     // orientation notch depth along Y, in from +Y edge (mm)

eps       = 0.5;   // overshoot for clean boolean cuts (mm)
$fn       = 64;    // facet count for round holes

// ---------------- Model ----------------
difference() {
    // Base plate, centred in XY, resting on z = 0
    translate([-plate_l/2, -plate_w/2, 0])
        cube([plate_l, plate_w, plate_t]);

    // 3 x 5 grid of through-holes, centred on the plate
    for (i = [0 : n_x - 1])
        for (j = [0 : n_y - 1])
            translate([(i - (n_x - 1)/2) * pitch,
                       (j - (n_y - 1)/2) * pitch,
                       -eps])
                cylinder(d = hole_d, h = plate_t + 2*eps);

    // Rectangular orientation notch in the +Y edge, centred on the Y axis
    translate([-notch_w/2, plate_w/2 - notch_d, -eps])
        cube([notch_w, notch_d + eps, plate_t + 2*eps]);
}
