// Bench rack for 50 x 0.65 mL microcentrifuge tubes
// Print orientation: block rests on XY plane, holes open upward (+Z)

$fn = 64;

// ---- Block dimensions ----
block_len    = 148;   // X length (mm)
block_wid    = 78;    // Y width (mm)
block_ht     = 25;    // Z height (mm)

// ---- Hole grid ----
cols         = 10;    // holes along X
rows         = 5;     // rows along Y
pitch        = 14;    // centre-to-centre spacing, both directions (mm)

// ---- Hole geometry ----
hole_d       = 9.0;   // hole diameter (mm)
hole_depth   = 21;    // hole depth from top surface (mm)
floor_t      = block_ht - hole_depth; // solid floor thickness = 4 mm

// ---- Cut overlap ----
eps          = 0.5;   // extension past top face to avoid coplanar faces

// Grid origin offsets so the grid is centred on the block
x0 = -(cols - 1) * pitch / 2;
y0 = -(rows - 1) * pitch / 2;

difference() {
    // Solid block, centred in XY, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // 5 x 10 grid of blind holes
