// Small lab funnel - printed upright, wide opening at top
$fn = 128;

// ---------- Dimensions (mm) ----------
spout_od     = 12.0;   // spout outer diameter
spout_h      = 18.0;   // spout height (z = 0 .. 18)
rim_od       = 60.0;   // cone outer diameter at rim
total_h      = 53.0;   // rim height (top of funnel)
wall         = 2.4;    // wall thickness (normal to surface)

// ---------- Derived values ----------
r_spout_o = spout_od / 2;                 // 6.0
r_spout_i = r_spout_o - wall;             // 3.6  -> 7.2 mm bore
r_rim_o   = rim_od / 2;                   // 30.0
cone_h    = total_h - spout_h;            // 35.0
cone_ang  = atan((r_rim_o - r_spout_o) / cone_h); // half-angle from vertical
h_off     = wall / cos(cone_ang);         // horizontal offset giving 2.4 mm normal wall
slope     = (r_rim_o - r_spout_o) / cone_h; // dr/dz of cone

// Inner cone surface: r = r_spout_o - h_off + (z - spout_h) * slope
r_rim_i   = r_rim_o - h_off;              // inner radius at rim
// z where inner cone meets the spout bore
z_join    = spout_h + (r_spout_i - (r_spout_o - h_off)) / slope;

// ---------- Profile (r, z) revolved around Z ----------
module funnel_profile() {
    polygon(points = [
        [r_spout_i, 0],          // bore bottom
        [r_spout_o, 0],          // spout outer bottom
        [r_spout_o, spout_h],    // spout/cone junction (outer)
        [r_rim_o,   total_h],    // rim outer
        [r_rim_i,   total_h],    // rim inner
        [r_spout_i, z_join]      // inner cone meets bore
    ]);
}

rotate_extrude($fn = 128)
    funnel_profile();
