// Small lab funnel - printed upright, wide rim at top
// Built as a single rotate_extrude profile, so the wall is 1.6 mm thick
// (measured normal to the surface) and the funnel is open at both ends.

$fn = 128;

// ---- Dimensions (mm) ----
spout_od     = 14.0;   // spout outer diameter
spout_h      = 20.0;   // spout height (z = 0 .. 20)
rim_od       = 50.0;   // cone outer diameter at rim
rim_z        = 45.0;   // rim height
wall         = 1.6;    // wall thickness everywhere

// ---- Derived values ----
r_out_spout  = spout_od / 2;                 // 7.0
r_in_spout   = r_out_spout - wall;           // 5.4 -> 10.8 mm bore
r_out_rim    = rim_od / 2;                   // 25.0
cone_h       = rim_z - spout_h;              // 25.0
slope        = (r_out_rim - r_out_spout) / cone_h;   // dr/dz of cone
h_off        = wall * sqrt(1 + slope * slope);       // horizontal offset giving 1.6 mm normal wall
r_in_rim     = r_out_rim - h_off;                    // inner radius at rim
// z where inner cone surface meets inner spout bore
z_join       = spout_h + (h_off - wall) / slope;

// ---- Funnel body ----
rotate_extrude(convexity = 4)
    polygon(points = [
        [r_in_spout,  0],          // bottom of bore
        [r_out_spout, 0],          // bottom outer edge
        [r_out_spout, spout_h],    // top of straight spout (outer)
        [r_out_rim,   rim_z],      // rim outer edge
        [r_in_rim,    rim_z],      // rim inner edge
        [r_in_spout,  z_join]      // inner cone meets bore
    ]);
