// ---------------- Base plate ----------------
base_x_min   = -20;   // base plate X start
base_x_max   = 20;    // base plate X end
base_y_min   = 0;     // base plate Y start (back edge)
base_y_max   = 40;    // base plate Y end (front edge)
base_thick   = 4;     // base plate thickness (Z)

// ---------------- Vertical plate ----------------
vert_x_min   = -20;   // vertical plate X start
vert_x_max   = 20;    // vertical plate X end
vert_y_min   = 0;     // vertical plate Y start
vert_thick   = 4;     // vertical plate thickness (Y)
vert_height  = 40;    // vertical plate height (Z)

// ---------------- Holes ----------------
hole_d       = 6.5;           // through-hole diameter
base_hole_xs = [-10, 10];     // base hole X positions
base_hole_y  = 25;            // base hole Y position
vert_hole_xs = [-10, 10];     // vertical plate hole X positions
vert_hole_z  = 22;            // vertical plate hole Z position

eps          = 0.5;           // cutter overshoot past faces

// ---------------- Derived ----------------
base_w = base_x_max - base_x_min;
base_l = base_y_max - base_y_min;
vert_w = vert_x_max - vert_x_min;

difference() {
    union() {
        // Base plate
        translate([base_x_min, base_y_min, 0])
            cube([base_w, base_l, base_thick]);

        // Vertical plate
        translate([vert_x_min, vert_y_min, 0])
            cube([vert_w, vert_thick, vert_height]);
    }

    // Vertical through-holes in base plate (along Z)
    for (x = base_hole_xs)
        translate([x, base_hole_y, -eps])
            cylinder(d = hole_d, h = base_thick + 2 * eps);

    // Horizontal through-holes in vertical plate (along Y)
    for (x = vert_hole_xs)
        translate([x, vert_y_min - eps, vert_hole_z])
            rotate([-90, 0, 0])
                cylinder(d = hole_d, h = vert_thick + 2 * eps);
}
