// Two-part enclosure: open-top box + lid (lid printed upside down)
// Both parts placed side by side on the bed, lid on +X side.

$fn = 64;

// ---------- Box ----------
box_x     = 90;    // box outer length (X)
box_y     = 40;    // box outer width (Y)
box_z     = 22;    // box outer height (Z)
wall_t    = 1.6;   // box wall thickness
floor_t   = 2.0;   // box floor thickness

// ---------- Lid ----------
lid_x     = 90;    // lid plate length (X)
lid_y     = 40;    // lid plate width (Y)
lid_t     = 2.0;   // lid plate thickness
lip_x     = 86.4;  // lip outer length (X)
lip_y     = 36.4;  // lip outer width (Y)
lip_t     = 2.0;   // lip wall thickness
lip_h     = 5;     // lip height above plate

// ---------- Layout ----------
gap       = 10;    // gap between parts on the bed
eps       = 0.5;   // overcut for clean differences

// Centre the pair on the origin in X
box_cx = -(box_x / 2 + gap / 2);   // box centre X
lid_cx =  (lid_x / 2 + gap / 2);   // lid centre X

// ---------- Modules ----------
module box() {
    difference() {
        translate([-box_x / 2, -box_y / 2, 0])
            cube([box_x, box_y, box_z]);
        // cavity, open at top
        translate([-(box_x - 2 * wall_t) / 2, -(box_y - 2 * wall_t) / 2, floor_t])
            cube([box_x - 2 * wall_t, box_y - 2 * wall_t, box_z - floor_t + eps]);
    }
}

module lid() {
    union() {
        // plate on the bed
        translate([-lid_x / 2, -lid_y / 2, 0])
            cube([lid_x, lid_y, lid_t]);
        // rectangular lip wall on top of the plate
        difference() {
            translate([-lip_x / 2, -lip_y / 2, lid_t - 0.01])
                cube([lip_x, lip_y, lip_h + 0.01]);
            translate([-(lip_x - 2 * lip_t) / 2, -(lip_y - 2 * lip_t) / 2, lid_t - eps])
                cube([lip_x - 2 * lip_t, lip_y - 2 * lip_t, lip_h + 2 * eps]);
        }
    }
}

// ---------- Build ----------
translate([box_cx, 0, 0]) box();
translate([lid_cx, 0, 0]) lid();
