// Replacement control knob for 6.0 mm D-shaft
// Print orientation: hotplate-facing side (bore opening) down on the bed

// ---------------- Parameters ----------------
knob_d        = 38.0;   // knob outer diameter
knob_h        = 14.0;   // knob total height

bore_d        = 6.2;    // D-bore circle diameter (clearance for 6.0 mm shaft)
bore_flat     = 4.5;    // distance from flat to opposite side of bore circle
bore_depth    = 10.0;   // blind bore depth from bottom face

groove_count  = 16;     // number of grip grooves
groove_d      = 2.0;    // grip groove diameter (half-cylinder on outer surface)

eps           = 0.5;    // cutter overlap past faces

$fn = 96;

// ---------------- Derived ----------------
knob_r     = knob_d / 2;
bore_r     = bore_d / 2;
flat_x     = bore_flat - bore_r;   // flat position from bore centre (+X side)

// ---------------- Modules ----------------
module d_bore_profile() {
    intersection() {
        circle(r = bore_r, $fn = 64);
        // keep everything from the far side of the circle up to the flat
        translate([-bore_r - eps, -bore_r - eps])
            square([flat_x + bore_r + eps, bore_d + 2 * eps]);
    }
}

module knob() {
    difference() {
        // main body
        cylinder(d = knob_d, h = knob_h, $fn = 128);

        // D-shaped blind bore from the bottom face
        translate([0, 0, -eps])
            linear_extrude(height = bore_depth + eps)
                d_bore_profile();

        // vertical grip grooves along full height
        for (i = [0 : groove_count - 1])
            rotate([0, 0, i * 360 / groove_count])
                translate([knob_r, 0, -eps])
                    cylinder(d = groove_d, h = knob_h + 2 * eps, $fn = 64);
    }
}

knob();
